import { spawnSync } from 'node:child_process'
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const pkg = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'))
const bun = process.env.BUN ?? 'bun'

function run(args, env = {}) {
  const result = spawnSync(bun, args, {
    cwd: root,
    env: { ...process.env, ...env },
    stdio: 'inherit',
  })
  if (result.error !== undefined) throw result.error
  if (result.status !== 0) {
    throw new Error(`bun ${args.join(' ')} exited with ${String(result.status)}`)
  }
}

mkdirSync(join(root, 'lib'), { recursive: true })
mkdirSync(join(root, '.build'), { recursive: true })

// Host half: a deliberately empty Cordis plugin. Its only job is to be a live
// Loader entry so dsh-client-modules can discover the package manifest and
// serve the browser bundle.
run(['build', 'src/index.ts', '--outfile', 'lib/index.js', '--format=esm', '--target=node'])

// Browser half. React and its JSX runtime are seeded by the Web shell's
// PLATFORM_MODULES table, so they stay external and resolve through the
// module loader's require.
run([
  'build',
  'src/client/index.tsx',
  '--outfile',
  '.build/client.body.cjs',
  '--format=cjs',
  '--target=browser',
  '--external',
  'react',
  '--external',
  'react/jsx-runtime',
], { NODE_ENV: 'production' })

const body = readFileSync(join(root, '.build/client.body.cjs'), 'utf8')
  .replace(/\n?\/\/# sourceMappingURL=.*$/u, '')
  .trimEnd()

if (body.includes('jsx-dev-runtime')) {
  throw new Error('client bundle still references react/jsx-dev-runtime; build it with NODE_ENV=production')
}

const indented = body
  .split('\n')
  .map((line) => `    ${line}`)
  .join('\n')

const wrapped = `/* Generated by scripts/build.mjs — do not edit by hand. */
window.__ModuleLoader__.load({
  id: ${JSON.stringify(pkg.name)},
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;
${indented}
    return module.exports;
  },
});
`

writeFileSync(join(root, 'lib/client.js'), wrapped)
console.log(`\nbuilt ${pkg.name}: lib/index.js + lib/client.js (${wrapped.length} bytes)`)
